import {createDonorAudio} from './donor-audio.js';
import * as THREE from 'three';
const colors={slash:0xe3e9ec,stab:0xe3e9ec,heavy:0xffa64c,special:0xe8bc65};
export function createEffects(scene,world,pistolAsset=null,getMuzzle=()=>null){const shots=[],transient=[],bolts=new Map(),loot=new Map(),sphere=new THREE.SphereGeometry(.15,8,6),gem=new THREE.OctahedronGeometry(.21),boltMaterial=new THREE.MeshBasicMaterial({color:0xee5526}),lootMaterials=[0xdca64d,0x48b9c5,0x70c66e].map(color=>new THREE.MeshBasicMaterial({color}));
 const pickup=new THREE.Group(),reticle=new THREE.Group();pickup.name='Starting pistol pickup';reticle.name='Pistol aim marker';
 const glowGeometry=new THREE.RingGeometry(.32,.43,32),glowMaterial=new THREE.MeshBasicMaterial({color:0xd9a750,transparent:true,opacity:.45,depthWrite:false,side:THREE.DoubleSide});
 const targetMaterial=new THREE.MeshBasicMaterial({color:0x76d4df,transparent:true,opacity:.6,depthWrite:false,depthTest:false,side:THREE.DoubleSide});
 const targetRing=new THREE.Mesh(glowGeometry,targetMaterial);targetRing.rotation.x=-Math.PI/2;targetRing.position.y=.04;targetRing.visible=false;reticle.add(targetRing);
 const glow=new THREE.Mesh(glowGeometry,glowMaterial);glow.rotation.x=-Math.PI/2;glow.position.y=.035;pickup.add(glow);
 if(pistolAsset){const gun=pistolAsset.scene.clone(true);gun.rotation.set(Math.PI/2,0,.45);gun.position.y=.15;gun.scale.setScalar(1.8);pickup.add(gun);}
 const crossGeometry=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-.18,.07,0),new THREE.Vector3(.18,.07,0),new THREE.Vector3(0,.07,-.18),new THREE.Vector3(0,.07,.18)]),crossMaterial=new THREE.LineBasicMaterial({color:0xf2d397,depthWrite:false,depthTest:false});reticle.add(new THREE.LineSegments(crossGeometry,crossMaterial));pickup.visible=reticle.visible=false;scene.add(pickup,reticle);
 function line(center,dir,radius,arc,color,expires,height=.08,stroke=false){const ring=arc>=359,points=[],steps=36,angle=Math.atan2(dir.x,-dir.z);if(!ring&&!stroke)points.push(new THREE.Vector3(0,height,0));for(let i=0;i<=steps;i++){const a=angle-arc*Math.PI/360+arc*Math.PI/180*i/steps;points.push(new THREE.Vector3(Math.sin(a)*radius,height,Math.cos(a)*radius));}if(!ring&&!stroke)points.push(new THREE.Vector3(0,height,0));const mesh=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color,transparent:true,opacity:.9,depthWrite:false}));mesh.position.copy(world.toRender(center));scene.add(mesh);transient.push({mesh,expires});}
 function erase(effect){scene.remove(effect.mesh);effect.mesh.geometry.dispose();effect.mesh.material.dispose();}
 return {events(game){for(const event of game.events){const actor=event.actor,donor=game.pilot==='donor-knife';
 if(event.type==='shot')shots.push(event);
 if(event.type==='enemy-attack' &&actor.swing)line(actor.pos,event.dir,event.range,event.arc,actor.kind===3?0xf9a83b:0xe45735,actor.swing.hitAt);
 if(event.type==='hit'&&donor&&!event.blocked&&event.amount>0)line(event.position??actor.pos,actor.facing,.16,360,0xe3bb9a,game.time+.08,.9,true);
 if(event.type==='strike'){if(donor&&event.action==='special')line(actor.pos,event.dir,1.3*(actor.combatScale??1.265),90,colors.special,game.time+.12,1.1,true);else if(event.action==='stab'){const a=world.toRender(actor.pos,1.1),b=a.clone().add(new THREE.Vector3(event.dir.x*1.8,0,-event.dir.z*1.8));const mesh=new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),new THREE.LineBasicMaterial({color:colors.stab,transparent:true,opacity:.85}));scene.add(mesh);transient.push({mesh,expires:game.time+.12});}else line(actor.pos,event.dir,event.action==='special'?4.2:event.action==='heavy'?1.8:1.5,event.action==='special'?360:120,colors[event.action],game.time+.12,1.1,true);}
 if(['parry','block','guard-break'].includes(event.type))line(donor?(event.position??actor.pos):actor.pos,actor.facing,1.05,donor&&event.type!=='guard-break'?120:360,event.type==='parry'?0x76d4df:event.type==='block'?0xc4a665:0xe95737,game.time+.18);
 }},update(game){for(let i=transient.length-1;i>=0;i--)if(game.time>=transient[i].expires||game.finished){erase(transient[i]);transient.splice(i,1);}
 for(const shot of shots){const muzzle=getMuzzle(),a=muzzle?muzzle.getWorldPosition(new THREE.Vector3()):world.toRender(shot.origin,1.05),b=world.toRender(shot.end,a.y),mesh=new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),new THREE.LineBasicMaterial({color:0xf5d498,transparent:true,opacity:.8,depthWrite:false}));scene.add(mesh);transient.push({mesh,expires:game.time+.09});line({x:a.x,z:-a.z},shot.direction,.15,360,0xffda8e,game.time+.06,a.y,true);}shots.length=0;
 const pistol=game.pistol;
 pickup.visible=!!pistol&&!pistol.collected&&world.areaId===pistol.pickupAreaId&&!game.finished;
 if(pickup.visible){pickup.position.copy(world.toRender(pistol.pickupPos));glowMaterial.opacity=.35+.12*Math.sin(game.time*2.4);}
 reticle.visible=!!pistol?.equipped&&!game.finished&&game.player.hp>0;
 if(reticle.visible){const p=game.player,target=game.enemies.find(e=>e.id===game.pistolTargetId&&e.hp>0);targetRing.visible=!!target;crossMaterial.color.setHex(target?0x76d4df:0xf2d397);reticle.position.copy(world.toRender(target?.pos??{x:p.pos.x+p.facing.x*4,z:p.pos.z+p.facing.z*4}));}
 const sync=(items,map,geometry,material,height)=>{const ids=new Set(items.map(x=>x.id));for(const [id,mesh]of map)if(!ids.has(id)){scene.remove(mesh);map.delete(id);}for(const item of items){let mesh=map.get(item.id);if(!mesh){mesh=new THREE.Mesh(geometry,typeof material==='function'?material(item):material);map.set(item.id,mesh);scene.add(mesh);}mesh.position.copy(world.toRender(item.pos,height));if(geometry===gem)mesh.rotation.y=game.time*1.5;}};
 sync(game.bolts,bolts,sphere,boltMaterial,.8);sync(game.loot,loot,gem,l=>lootMaterials[l.kind],.3);
 },reset(){shots.length=0;pickup.visible=reticle.visible=false;for(const e of transient)erase(e);transient.length=0;for(const map of [bolts,loot]){for(const mesh of map.values())scene.remove(mesh);map.clear();}},dispose(){this.reset();scene.remove(pickup,reticle);glowGeometry.dispose();glowMaterial.dispose();crossGeometry.dispose();crossMaterial.dispose();targetMaterial.dispose();sphere.dispose();gem.dispose();boltMaterial.dispose();for(const m of lootMaterials)m.dispose();}};
}
// Small local cues: start audio only on the player's Enter/Resume gesture.
export function createAudio(options={}){if(options.donor)return createDonorAudio(options);let context=null,enabled=true;return {async unlock(){context??=new(window.AudioContext||window.webkitAudioContext)();await context.resume();},setEnabled(value){enabled=value;},pause(){if(context?.state==='running')context.suspend();},play(events){if(!enabled||context?.state!=='running')return;for(const e of events){const frequencies={attack:180,hit:95,parry:660,block:260,dodge:120,loot:880,death:55,wave:330};const frequency=frequencies[e.type];if(!frequency)continue;const oscillator=context.createOscillator(),gain=context.createGain(),start=context.currentTime,duration=e.type==='death'?.25:.08;oscillator.type=e.type==='loot'||e.type==='parry'?'sine':'triangle';oscillator.frequency.setValueAtTime(frequency,start);oscillator.frequency.exponentialRampToValueAtTime(Math.max(30,frequency*.55),start+duration);gain.gain.setValueAtTime(.035,start);gain.gain.exponentialRampToValueAtTime(.001,start+duration);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+duration);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();};}}};}
